import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        n = int(next(iterator))
        a = []
        for _ in range(n):
            a.append(int(next(iterator)))
    except StopIteration:
        return

    b = sorted(a)

    if a != b:
        pos_map = {}
        for i in range(n):
            val = b[i]
            if val not in pos_map:
                pos_map[val] = []
            pos_map[val].append(i)

        current_pos = {val: [] for val in set(b)}
        for val in current_pos:
            current_pos[val] = []

        count_used = {val: 0 for val in set(b)}

        operations = []

        for i in range(n):
            target_val = b[i]
            current_val = a[i]

            if current_val != target_val:
                j = i + 1
                while j < n:
                    if a[j] == target_val:
                        break
                    j += 1

                if j == n:
                    print("-1")
                    return

                if a[i] > a[j]:
                    operations.append((i + 1, j + 1))
                    a[i], a[j] = a[j], a[i]
                else:
                    print("-1")
                    return

        if a != b:
            print("-1")
            return

        final_pairs = []
        temp_a = list(a)
        for u, v in operations:
            u_idx = u - 1
            v_idx = v - 1
            if temp_a[u_idx] > temp_a[v_idx]:
                final_pairs.append((u, v))
                temp_a[u_idx], temp_a[v_idx] = temp_a[v_idx], temp_a[u_idx]
            else:
                pass

        if temp_a != b:
            print("-1")
            return

        print(len(final_pairs))
        for u, v in final_pairs:
            print(f"{u} {v}")
    else:
        print("0")

if __name__ == "__main__":
    solve()
